import {read,write,esc} from './research-store.mjs';
const key='meme-fast-radar-sources-v1',$=id=>document.getElementById(id);let sources=read(key,[]);if(!Array.isArray(sources))sources=[];
function draw(){$('list').innerHTML=sources.length?sources.map(s=>`<div class="source-card"><div><strong>${esc(s.handle)}</strong><small>${esc(s.category)} · ${esc(s.group)} · weight ${Number(s.weight)}/5</small></div><div><span class="source-badge">NOT CONNECTED</span> <button type="button" data-remove="${esc(s.handle)}">Remove</button></div></div>`).join(''):'<div class="empty-workspace"><strong>No X accounts saved.</strong>Add accounts to define the collector’s future coverage.</div>'}
$('form').onsubmit=e=>{e.preventDefault();const handle='@'+$('handle').value.replace(/^@/,'');if(sources.some(s=>s.handle.toLowerCase()===handle.toLowerCase())){$('status').textContent='That account is already saved.';return}sources.push({handle,category:$('category').value,group:$('group').value,weight:Number($('weight').value)});write(key,sources);$('handle').value='';$('status').textContent='Account saved locally. X collection is not connected yet.';draw()};
$('list').onclick=e=>{const button=e.target.closest('[data-remove]');if(button){sources=sources.filter(s=>s.handle!==button.dataset.remove);write(key,sources);draw()}};draw();
